import{familyIconURL}from'./family-icons.mjs';
export const requestStatus={pending:'بانتظار المراجعة',approved:'تم الاعتماد',published:'منشور',pending_manager:'بانتظار موافقة المدير',post_rejected:'لم يعتمد المدير النشر',rejected:'مرفوض',cancelled:'ملغى'};
export function renderTemplate(pattern,fields){return pattern.replace(/\{(subject|newborn|bride_father|details|requester)\}/g,(_,key)=>fields[key]||'')}
export function brandNewsCard(card,family){card.classList.add('requested-news-card');const mark=document.createElement('img');mark.className='requested-news-watermark';mark.src=familyIconURL(family);mark.alt='';mark.setAttribute('aria-hidden','true');card.prepend(mark)}
export function initNewsRequests(c){const{state,tenants,req,element:E,button:B,busy,toast}=c;const call=(action,payload={})=>req('/rest/v1/rpc/news_request_action',{method:'POST',body:{action,payload}});let meta={},epoch=0;
 function dialog(title){const d=E('dialog',undefined,'news-request-dialog');d.append(E('h2',title),B('إغلاق',()=>{d.close();d.remove()},'text-button'));document.body.append(d);d.showModal();return d}
 function field(form,label,type='text',value=''){const l=E('label',label),input=E(type==='textarea'?'textarea':'input');if(type!=='textarea')input.type=type;input.value=value;l.append(input);form.append(l);return input}
 function preview(parent,title,text){const box=E('article',undefined,'news-request-preview');brandNewsCard(box,tenants.selected);box.append(E('h3',title),E('p',text));parent.append(box);return box}
 const submit=B('طلب نشر خبر',()=>busy(submit,openSubmit),'text-button'),mine=B('طلبات أخباري',()=>busy(mine,()=>openList(false)),'text-button'),review=B('مراجعة طلبات نشر الأخبار',()=>busy(review,()=>openList(true)),'text-button'),templates=B('أنواع الأخبار المحفوظة',()=>busy(templates,openTemplates),'text-button');for(const b of[submit,mine,review,templates]){b.hidden=true;document.querySelector('.app-nav').append(b)}
 const plus=B('＋',()=>busy(plus,openSubmit),'request-news-plus primary');plus.id='request-news-plus';plus.title='طلب نشر خبر';plus.setAttribute('aria-label','طلب نشر خبر');plus.hidden=true;document.querySelector('#news-section>.feed-heading').append(plus);
 async function openSubmit(){const d=dialog('طلب نشر خبر'),rows=(await call('templates')).filter(t=>t.enabled);if(!rows.length){d.append(E('p','لم يضف مدير العائلة أنواع الأخبار وصيغها بعد.'));return}const form=E('form'),select=E('select'),label=E('label','عنوان الخبر / نوع الخبر');for(const t of rows){const o=E('option',t.name);o.value=t.id;select.append(o)}label.append(select);form.append(label);const subject=field(form,'اسم صاحب الخبر · المعني بالخبر'),newborn=field(form,'اسم المولود'),bride=field(form,'كريمة من · اسم والد العروس'),details=field(form,'تفاصيل أخرى','textarea');subject.required=true;subject.maxLength=newborn.maxLength=bride.maxLength=250;details.maxLength=2000;details.rows=4;const p=preview(form,'',''),save=E('button','إرسال الطلب للصحفيين والمدير','primary');save.disabled=!!state.readOnly;form.append(save);d.append(form);let requestID=crypto.randomUUID();function paint(){const t=rows.find(t=>t.id===select.value);newborn.parentElement.hidden=t.kind!=='newborn';bride.parentElement.hidden=t.kind!=='marriage';newborn.required=t.kind==='newborn';bride.required=t.kind==='marriage';p.querySelector('h3').textContent=t.name;p.querySelector('p').textContent=renderTemplate(t.body,{subject:subject.value,newborn:newborn.value,bride_father:bride.value,details:details.value,requester:state.profile.display_name})}select.onchange=paint;for(const input of[subject,newborn,bride,details])input.oninput=paint;paint();form.onsubmit=e=>{e.preventDefault();return busy(save,async()=>{await call('submit',{request_id:requestID,template:select.value,subject:subject.value,newborn:newborn.value,bride_father:bride.value,details:details.value});requestID=crypto.randomUUID();d.close();d.remove();await refresh();toast('أُرسل طلبك إلى الصحفيين ومدير العائلة.');await openList(false)})}}
 async function openList(isReview){const d=dialog(isReview?'طلبات نشر الأخبار':'طلبات أخباري'),box=E('div'),more=B('طلبات أقدم',()=>busy(more,()=>load(false)),'secondary');d.append(box,more);let offset=0;async function load(reset){const rows=await call('list',{review:isReview,offset:reset?0:offset});if(!d.open)return;if(reset){box.replaceChildren();offset=0}offset+=rows.length;for(const r of rows){const card=E('article',undefined,'news-request-row');card.append(E('h3',r.title),E('p',r.requester_name+' · '+(requestStatus[r.display_status]||r.status)));preview(card,r.title,r.rendered_body);if(r.review_note)card.append(E('p','ملاحظة المراجع: '+r.review_note));if(r.post_id)card.append(B('فتح الخبر',()=>{d.close();d.remove();document.dispatchEvent(new CustomEvent('family:news',{detail:{id:String(r.post_id)}}))},'secondary'));if(r.status==='pending'){if(isReview){card.append(B('مراجعة واعتماد',()=>busy(null,async()=>{await openApproval(r);}), 'primary'),B('رفض الطلب',()=>busy(null,async()=>{const note=prompt('سبب الرفض (اختياري)');if(note===null)return;await call('reject',{id:r.id,note});await load(true);await refresh()}),'secondary'))}else card.append(B('إلغاء الطلب',()=>busy(null,async()=>{await call('cancel',{id:r.id});await load(true)}),'text-button danger'))}box.append(card)}more.hidden=rows.length<30;if(!offset)box.append(E('p','لا توجد طلبات.'))}d.addEventListener('news-request-updated',()=>busy(null,()=>load(true)));await load(true)}
 async function openApproval(r){const d=dialog('اعتماد صيغة الخبر والمنشن'),form=E('form'),title=field(form,'عنوان النشر','text',r.title),body=field(form,'الصيغة النهائية','textarea',r.rendered_body);title.required=true;title.maxLength=250;body.required=true;body.maxLength=10000;body.rows=8;const requester=E('input'),rl=E('label','منشن مباشر لطالب الخبر: '+r.requester_name,'inline');requester.type='checkbox';rl.prepend(requester);form.append(rl);const search=field(form,'إضافة أعضاء للمنشن · الاسم أو الجوال'),results=E('div'),chosenBox=E('div'),chosen=new Map;form.append(results,chosenBox);let timer,seq=0;search.oninput=()=>{clearTimeout(timer);const n=++seq;const term=search.value.trim().replace(/^@/,'');if(!term){results.replaceChildren();return}timer=setTimeout(()=>busy(search,async()=>{const rows=await call('mention_search',{term});if(n!==seq||!d.open)return;results.replaceChildren();for(const p of rows)results.append(B(p.display_name,()=>{if(chosen.size>=20&&!chosen.has(p.id))throw Error('حتى 20 منشن للخبر');chosen.set(p.id,p);paint();results.replaceChildren();search.value=''},'secondary'))}),250)};function paint(){chosenBox.replaceChildren();for(const p of chosen.values())chosenBox.append(B('✕ '+p.display_name,()=>{chosen.delete(p.id);paint()},'secondary'))}const save=E('button','اعتماد وإرسال للنشر','primary');save.disabled=!!state.readOnly;form.append(E('p','تطبق موافقة المدير على أخبار الصحفي وفق إعدادات العائلة.','muted'),save);form.onsubmit=e=>{e.preventDefault();return busy(save,async()=>{const result=await call('approve',{id:r.id,title:title.value,body:body.value,mentions:[...chosen.keys()],mention_requester:requester.checked});d.close();d.remove();document.querySelectorAll('.news-request-dialog').forEach(x=>x.dispatchEvent(new Event('news-request-updated')));await refresh();toast(result.published?'اعتمد الخبر ونُشر.':'وصل الخبر إلى المدير للموافقة النهائية.');if(result.published)document.dispatchEvent(new CustomEvent('family:news',{detail:{id:String(result.post_id)}}))})};d.addEventListener('close',()=>{clearTimeout(timer);seq++});d.append(form)}
 const addType=B('＋ إضافة نوع خبر وصياغته',()=>busy(addType,()=>openTemplates(true)),'primary');addType.id='news-type-add-open';addType.hidden=true;const managerTypes=E('section',undefined,'news-type-manager-card');managerTypes.append(E('h3','أنواع الأخبار وصيغ طلب النشر'),E('p','أضف عنوان النوع، واكتب الصيغة، ثم اضغط موضع النص وأدرج بيانات الطلب. يظهر النوع المحفوظ مباشرة في نموذج طلب نشر خبر.'),addType);managerTypes.hidden=true;document.getElementById('settings-section').append(managerTypes);templates.id='news-types-open';
 async function openTemplates(startNew=false){const d=dialog('أنواع الأخبار والصيغ الجاهزة'),box=E('div');d.append(B('＋ إضافة نوع خبر وصياغته',()=>editTemplate(null),'primary'),box);async function load(){const rows=await call('templates');box.replaceChildren();for(const t of rows){const row=E('article',undefined,'news-request-row');row.append(E('h3',t.name+(t.enabled?'':' · موقوف')),E('p',t.body),B('تعديل الصيغة والنوع',()=>editTemplate(t),'secondary'));box.append(row)}}async function editTemplate(t){const panel=dialog(t?'تعديل نوع الخبر وصياغته':'إضافة نوع خبر وصياغته'),f=E('form'),name=field(f,'١. اسم نوع الخبر · يظهر في قائمة أنواع الأخبار','text',t?.name||''),kind=E('select');for(const[v,l]of[['general','عام'],['newborn','مولود جديد'],['marriage','عقد قران']]){const o=E('option',l);o.value=v;kind.append(o)}kind.value=t?.kind||'general';const kindLabel=E('label','تصنيف الحقول المطلوبة');kindLabel.append(kind);f.append(kindLabel);const pattern=field(f,'٢. صياغة الخبر · اضغط مكان ظهور البيانات داخل النص','textarea',t?.body||'تتقدم العائلة بالتهنئة إلى {subject}\n{details}');pattern.rows=7;pattern.required=name.required=true;name.maxLength=100;pattern.maxLength=6000;const tokens=E('div',undefined,'template-field-tokens');tokens.append(E('p','٣. ضع المؤشر في الصيغة ثم اختر الحقل لإدراجه في نفس المكان:'));for(const[key,label]of[['subject','اسم صاحب الخبر'],['newborn','اسم المولود'],['bride_father','كريمة من'],['details','تفاصيل أخرى'],['requester','اسم طالب الخبر']])tokens.append(B('＋ '+label,()=>{const a=pattern.selectionStart,b=pattern.selectionEnd;pattern.setRangeText('{'+key+'}',a,b,'end');pattern.focus();paint()},'secondary'));pattern.before(tokens);const enabled=E('input'),enabledLabel=E('label','إتاحة النوع للأعضاء','inline');enabled.type='checkbox';enabled.checked=t?.enabled??true;enabledLabel.prepend(enabled);f.append(enabledLabel);const p=preview(f,name.value,'');function paint(){p.querySelector('h3').textContent=name.value;p.querySelector('p').textContent=renderTemplate(pattern.value,{subject:'أحمد علي',newborn:'علي',bride_father:'محمد حسن',details:'تفاصيل الخبر هنا',requester:'طالب الخبر'})}pattern.oninput=name.oninput=paint;paint();const save=E('button','حفظ وإضافة النوع إلى قائمة الأخبار','primary');save.disabled=!!state.readOnly;f.append(save);panel.append(f);f.onsubmit=e=>{e.preventDefault();return busy(save,async()=>{await call('template_save',{id:t?.id||null,name:name.value,kind:kind.value,body:pattern.value,enabled:enabled.checked});panel.close();panel.remove();await load();toast('حُفظ نوع الخبر وأصبح متاحًا في قائمة طلب نشر خبر.')})}}await load();if(startNew===true)await editTemplate(null)}
 async function refresh(){const n=++epoch;const active=state.user&&state.profile?.status==='active';plus.hidden=submit.hidden=mine.hidden=review.hidden=templates.hidden=!active;managerTypes.hidden=addType.hidden=!active;if(!active)return;meta=await call('meta');if(n!==epoch)return;review.hidden=!meta.writer;managerTypes.hidden=addType.hidden=templates.hidden=!meta.admin;review.textContent='مراجعة طلبات نشر الأخبار'+(meta.pending?' · '+meta.pending:'')}
 const timer=setInterval(()=>{if(state.user&&!document.hidden)refresh().catch(()=>{})},30000);timer.unref?.();return{refresh,openSubmit,reset(){epoch++;managerTypes.hidden=addType.hidden=plus.hidden=true;for(const b of[submit,mine,review,templates])b.hidden=true;document.querySelectorAll('.news-request-dialog').forEach(d=>d.remove())}}
}
